1	import { lazy, Suspense, useEffect } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	import { supabase } from "@/integrations/supabase/client";
14	
15	// Eager imports — core pages users navigate between constantly (no Suspense flash)
16	import Index from "./pages/Index";
17	import Auth from "./pages/Auth";
18	import Settings from "./pages/Settings";
19	import Profile from "./pages/Profile";
20	import Billing from "./pages/Billing";
21	import Team from "./pages/Team";
22	import Tasks from "./pages/Tasks";
23	import Activity from "./pages/Activity";
24	
25	// Sidebar-accessible pages — eager to avoid flash on click
26	import Changelog from "./pages/Changelog";
27	import RequestFeature from "./pages/RequestFeature";
28	import CareerSettings from "./pages/CareerSettings";
29	import Integrations from "./pages/Integrations";
30	import Reports from "./pages/Reports";
31	import AgencyHub from "./pages/AgencyHub";
32	import TalentPool from "./pages/TalentPool";
33	
34	// Lazy imports — infrequent or large pages
35	const Admin = lazy(() => import("./pages/Admin"));
36	const NotFound = lazy(() => import("./pages/NotFound"));
37	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
38	const BookDemo = lazy(() => import("./pages/BookDemo"));
39	const Apply = lazy(() => import("./pages/Apply"));
40	const CareerPage = lazy(() => import("./pages/CareerPage"));
41	const CareerJobDetail = lazy(() => import("./pages/CareerJobDetail"));
42	const LandingPage = lazy(() => import("@/components/LandingPage"));
43	const SharedPortal = lazy(() => import("./pages/SharedPortal"));
44	const BookInterview = lazy(() => import("./pages/BookInterview"));
45	
46	const queryClient = new QueryClient({
47	  defaultOptions: {
48	    queries: {
49	      staleTime: 5 * 60 * 1000,
50	      gcTime: 10 * 60 * 1000,
51	      refetchOnWindowFocus: false,
52	      refetchOnMount: false,
53	      retry: 1,
54	    },
55	  },
56	});
57	
58	/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
59	const PageLoader = () => (
60	  <div className="flex h-svh w-full overflow-hidden">
61	    {/* Sidebar skeleton — matches sidebar width */}
62	    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
63	      <div className="px-4 py-4">
64	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
65	      </div>
66	      <div className="border-t border-border" />
67	      <div className="p-3 space-y-2">
68	        {[1, 2, 3, 4].map((i) => (
69	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
70	        ))}
71	      </div>
72	    </div>
73	    {/* Content area skeleton */}
74	    <div className="flex-1 flex flex-col min-w-0">
75	      {/* Header skeleton */}
76	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
77	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
78	        <div className="flex items-center gap-3">
79	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
80	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
81	        </div>
82	      </div>
83	      {/* Body skeleton */}
84	      <div className="flex-1 overflow-y-auto p-6">
85	        <div className="max-w-5xl mx-auto space-y-4">
86	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
87	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
88	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
89	            {[1, 2, 3, 4].map((i) => (
90	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
91	            ))}
92	          </div>
93	        </div>
94	      </div>
95	    </div>
96	  </div>
97	);
98	
99	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
100	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
101	  const { isAdmin, loading } = useAuth();
102	
103	  // Don't block rendering while loading — only gate when we know maintenance is on
104	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
105	  return <>{children}</>;
106	};
107	
108	const RootRoute = () => {
109	  const { user, loading } = useAuth();
110	  if (loading) return <PageLoader />;
111	  return user ? <Index /> : <LandingPage />;
112	};
113	
114	/** Silently prefetches sidebar-linked pages so they open instantly on first click */
115	const DataPrefetcher = () => {
116	  const { user } = useAuth();
117	  const qc = useQueryClient();
118	
119	  useEffect(() => {
120	    // Prefetch public data that doesn't require auth
121	    qc.prefetchQuery({
122	      queryKey: ["changelog_public"],
123	      queryFn: async () => {
124	        const { data } = await (supabase as any)
125	          .from("changelog")
126	          .select("id, version, title, description, category, published_at")
127	          .eq("status", "published")
128	          .order("published_at", { ascending: false });
129	        return data ?? [];
130	      },
131	      staleTime: 5 * 60 * 1000,
132	    });
133	    qc.prefetchQuery({
134	      queryKey: ["feature_requests"],
135	      queryFn: async () => {
136	        const { data } = await (supabase as any)
137	          .from("feature_requests")
138	          .select("*")
139	          .order("created_at", { ascending: false });
140	        return data ?? [];
141	      },
142	      staleTime: 5 * 60 * 1000,
143	    });
144	  }, []);
145	
146	  useEffect(() => {
147	    if (!user) return;
148	    qc.prefetchQuery({
149	      queryKey: ["my_feature_votes"],
150	      queryFn: async () => {
151	        const { data } = await (supabase as any)
152	          .from("feature_request_votes")
153	          .select("feature_request_id")
154	          .eq("user_id", user.id);
155	        return (data ?? []).map((v: any) => v.feature_request_id);
156	      },
157	      staleTime: 5 * 60 * 1000,
158	    });
159	  }, [user?.id]);
160	
161	  return null;
162	};
163	
164	const App = () => (
165	  <QueryClientProvider client={queryClient}>
166	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
167	      <AuthProvider>
168	        <DataPrefetcher />
169	        <TooltipProvider>
170	          <Sonner />
171	          <BrowserRouter>
172	            <SeoHead />
173	            <Suspense fallback={<PageLoader />}>
174	              <Routes>
175	                {/* Public pages — outside MaintenanceGate so candidates/guests can always access */}
176	                <Route path="/apply/:jobId" element={<Apply />} />
177	                <Route path="/careers/:slug" element={<CareerPage />} />
178	                <Route path="/careers/:slug/jobs/:jobId" element={<CareerJobDetail />} />
179	                <Route path="/shared/:token" element={<SharedPortal />} />
180	                <Route path="/book/:token" element={<BookInterview />} />
181	                <Route path="*" element={
182	                  <MaintenanceGate>
183	                    <Routes>
184	                      <Route path="/auth" element={<Auth />} />
185	                      <Route path="/" element={<RootRoute />} />
186	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
187	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
188	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
189	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
190	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
191	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
192	                      <Route path="/activity" element={<ProtectedRoute><Activity /></ProtectedRoute>} />
193	                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
194	                      <Route path="/integrations" element={<ProtectedRoute><Integrations /></ProtectedRoute>} />
195	                      <Route path="/reports" element={<ProtectedRoute><Reports /></ProtectedRoute>} />
196	                      <Route path="/agency" element={<ProtectedRoute><AgencyHub /></ProtectedRoute>} />
197	                      <Route path="/talent-pool" element={<ProtectedRoute><TalentPool /></ProtectedRoute>} />
198	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
199	                      <Route path="/book-demo" element={<BookDemo />} />
200	                      <Route path="/request-feature" element={<RequestFeature />} />
201	                      <Route path="/changelog" element={<Changelog />} />
202	                      <Route path="/payment/callback" element={<PaymentCallback />} />
203	                      <Route path="*" element={<NotFound />} />
204	                    </Routes>
205	                  </MaintenanceGate>
206	                } />
207	              </Routes>
208	            </Suspense>
209	            <ChatWidget />
210	          </BrowserRouter>
211	        </TooltipProvider>
212	      </AuthProvider>
213	    </ThemeProvider>
214	  </QueryClientProvider>
215	);
216	
217	export default App;
218	
