1	import React, { useState, useEffect, useCallback } from "react";
2	import { useAuth } from "@/hooks/useAuth";
3	import { supabase } from "@/integrations/supabase/client";
4	import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
5	import { Button } from "@/components/ui/button";
6	import { Separator } from "@/components/ui/separator";
7	import { Bell, CheckCircle2, AlertCircle, FileText, Coins, Info, CheckCheck, ArrowRight, MessageSquare, CheckSquare, UserPlus, AtSign } from "lucide-react";
8	import { cn } from "@/lib/utils";
9	import { formatDistanceToNow } from "date-fns";
10	
11	// ─── Types ──────────────────────────────────────────────────────────────────
12	
13	interface Notification {
14	  id: string;
15	  type: "ranking_complete" | "ranking_failed" | "credits_low" | "credits_added" | "system"
16	    | "stage_changed" | "note_added" | "task_assigned" | "task_completed" | "member_joined" | "mention";
17	  title: string;
18	  message: string;
19	  read: boolean;
20	  created_at: string;
21	  metadata?: Record<string, any>;
22	}
23	
24	const ICON_MAP: Record<Notification["type"], { icon: typeof Bell; color: string; bg: string }> = {
25	  ranking_complete: { icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-100" },
26	  ranking_failed: { icon: AlertCircle, color: "text-destructive", bg: "bg-destructive/10" },
27	  credits_low: { icon: Coins, color: "text-amber-600", bg: "bg-amber-100" },
28	  credits_added: { icon: Coins, color: "text-blue-600", bg: "bg-blue-100" },
29	  system: { icon: Info, color: "text-muted-foreground", bg: "bg-muted" },
30	  stage_changed: { icon: ArrowRight, color: "text-violet-600", bg: "bg-violet-100" },
31	  note_added: { icon: MessageSquare, color: "text-blue-600", bg: "bg-blue-100" },
32	  task_assigned: { icon: CheckSquare, color: "text-orange-600", bg: "bg-orange-100" },
33	  task_completed: { icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-100" },
34	  member_joined: { icon: UserPlus, color: "text-primary", bg: "bg-primary/10" },
35	  mention: { icon: AtSign, color: "text-cyan-600", bg: "bg-cyan-100" },
36	};
37	
38	// ─── Component ──────────────────────────────────────────────────────────────
39	
40	const NotificationBell = () => {
41	  const { user } = useAuth();
42	  const [open, setOpen] = useState(false);
43	  const [notifications, setNotifications] = useState<Notification[]>([]);
44	  const [loading, setLoading] = useState(false);
45	
46	  const unreadCount = notifications.filter((n) => !n.read).length;
47	
48	  const fetchNotifications = useCallback(async () => {
49	    if (!user) return;
50	    setLoading(true);
51	    try {
52	      const { data } = await supabase
53	        .from("notifications")
54	        .select("id, type, title, message, read, created_at, metadata")
55	        .eq("user_id", user.id)
56	        .order("created_at", { ascending: false })
57	        .limit(20);
58	      if (data) setNotifications(data as Notification[]);
59	    } catch {
60	      // Silently fail — notifications are non-critical
61	    } finally {
62	      setLoading(false);
63	    }
64	  }, [user]);
65	
66	  // Initial fetch for badge count
67	  useEffect(() => {
68	    fetchNotifications();
69	  }, [fetchNotifications]);
70	
71	  // Refresh when popover opens
72	  useEffect(() => {
73	    if (open) fetchNotifications();
74	  }, [open, fetchNotifications]);
75	
76	  // Real-time subscription for new notifications
77	  useEffect(() => {
78	    if (!user) return;
79	
80	    const channel = supabase
81	      .channel("notifications")
82	      .on(
83	        "postgres_changes",
84	        {
85	          event: "INSERT",
86	          schema: "public",
87	          table: "notifications",
88	          filter: `user_id=eq.${user.id}`,
89	        },
90	        (payload) => {
91	          setNotifications((prev) => [payload.new as Notification, ...prev].slice(0, 20));
92	        }
93	      )
94	      .subscribe();
95	
96	    return () => {
97	      supabase.removeChannel(channel);
98	    };
99	  }, [user?.id]);
100	
101	  const markAsRead = async (id: string) => {
102	    setNotifications((prev) =>
103	      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
104	    );
105	    await supabase.from("notifications").update({ read: true }).eq("id", id);
106	  };
107	
108	  const markAllAsRead = async () => {
109	    if (unreadCount === 0) return;
110	    const unreadIds = notifications.filter((n) => !n.read).map((n) => n.id);
111	    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
112	    await supabase.from("notifications").update({ read: true }).in("id", unreadIds);
113	  };
114	
115	  return (
116	    <Popover open={open} onOpenChange={setOpen}>
117	      <PopoverTrigger asChild>
118	        <button
119	          className="relative h-9 w-9 rounded-lg bg-muted flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1"
120	          aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ""}`}
121	        >
122	          <Bell className="h-4 w-4" />
123	          {unreadCount > 0 && (
124	            <span className="absolute -top-0.5 -right-0.5 flex items-center justify-center min-w-[18px] h-[18px] px-1 rounded-full bg-primary text-primary-foreground text-[10px] font-bold leading-none shadow-sm">
125	              {unreadCount > 99 ? "99+" : unreadCount}
126	            </span>
127	          )}
128	        </button>
129	      </PopoverTrigger>
130	
131	      <PopoverContent align="end" className="w-80 p-0">
132	        {/* Header */}
133	        <div className="flex items-center justify-between px-4 pt-3.5 pb-3">
134	          <h3 className="text-sm font-semibold text-foreground">Notifications</h3>
135	          {unreadCount > 0 && (
136	            <button
137	              onClick={markAllAsRead}
138	              className="inline-flex items-center gap-1 text-[11px] font-medium text-primary hover:text-primary/80 transition-colors"
139	            >
140	              <CheckCheck className="h-3 w-3" />
141	              Mark all read
142	            </button>
143	          )}
144	        </div>
145	
146	        <Separator />
147	
148	        {/* Notification list */}
149	        <div className="max-h-[360px] overflow-y-auto">
150	          {loading && notifications.length === 0 ? (
151	            <div className="px-4 py-8 text-center">
152	              <div className="h-4 w-4 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" />
153	              <p className="text-xs text-muted-foreground mt-2">Loading...</p>
154	            </div>
155	          ) : notifications.length === 0 ? (
156	            <div className="px-4 py-10 text-center">
157	              <Bell className="h-8 w-8 text-muted-foreground/30 mx-auto mb-2" />
158	              <p className="text-sm text-muted-foreground">No notifications yet</p>
159	              <p className="text-xs text-muted-foreground/70 mt-0.5">
160	                We'll notify you about job rankings and updates.
161	              </p>
162	            </div>
163	          ) : (
164	            notifications.map((notification) => {
165	              const style = ICON_MAP[notification.type] ?? ICON_MAP.system;
166	              const Icon = style.icon;
167	
168	              return (
169	                <button
170	                  key={notification.id}
171	                  onClick={() => markAsRead(notification.id)}
172	                  className={cn(
173	                    "w-full text-left px-4 py-3 flex gap-3 hover:bg-muted/50 transition-colors border-b border-border last:border-0",
174	                    !notification.read && "bg-primary/[0.03]"
175	                  )}
176	                >
177	                  <div className={cn("h-8 w-8 rounded-lg flex items-center justify-center shrink-0 mt-0.5", style.bg)}>
178	                    <Icon className={cn("h-4 w-4", style.color)} />
179	                  </div>
180	                  <div className="min-w-0 flex-1">
181	                    <div className="flex items-start justify-between gap-2">
182	                      <p className={cn("text-sm leading-tight truncate", !notification.read ? "font-semibold text-foreground" : "font-medium text-foreground/80")}>
183	                        {notification.title}
184	                      </p>
185	                      {!notification.read && (
186	                        <span className="h-2 w-2 rounded-full bg-primary shrink-0 mt-1.5" />
187	                      )}
188	                    </div>
189	                    <p className="text-xs text-muted-foreground line-clamp-2 mt-0.5">
190	                      {notification.message}
191	                    </p>
192	                    <p className="text-[10px] text-muted-foreground/60 mt-1">
193	                      {formatDistanceToNow(new Date(notification.created_at), { addSuffix: true })}
194	                    </p>
195	                  </div>
196	                </button>
197	              );
198	            })
199	          )}
200	        </div>
201	      </PopoverContent>
202	    </Popover>
203	  );
204	};
205	
206	export default React.memo(NotificationBell);
207	
